"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94005"],{90368(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.eliminacao_indevida","status":422,"titulo":"Regras de elimina\xe7\xe3o n\xe3o se aplicam quando a classifica\xe7\xe3o \xe9 importada"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.eliminacao_indevida","requisitos":[],"oQueAconteceu":["A regra de c\xe1lculo declarada \xe9 `CLASSIFICACAO_IMPORTADA`, mas a configura\xe7\xe3o\\ntamb\xe9m informou uma ou mais regras de elimina\xe7\xe3o. Eliminar por corte de nota\\npressup\xf5e um c\xe1lculo feito localmente \u2014 quando o resultado j\xe1 vem pronto de\\noutra origem, persistir uma regra de elimina\xe7\xe3o junto criaria um estado\\ncontradit\xf3rio (o corte se aplicaria a uma nota que o sistema nunca calculou).","No caminho de defini\xe7\xe3o, pode coexistir na mesma resposta com\\n[`arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_indevido)\\ne\\n[`casas_arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_indevido)\\n(acumula, ADR-0125). Nunca coexiste com\\n[`arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_obrigatorio)\\nnem com\\n[`casas_arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_obrigatorio)\\n\u2014 pertencem ao ramo oposto (c\xe1lculo local).","Reprovar aqui **n\xe3o** esvazia a lista de regras de elimina\xe7\xe3o que a\\nconfigura\xe7\xe3o carrega para a confer\xeancia seguinte \u2014 as regras continuam ali,\\napenas marcadas como incoerentes. Por isso, se a lista incluir uma regra\\n`ELIMINACAO_CORTE_EM_AREA` ou `ELIMINACAO_ZERO_EM_AREA` e a configura\xe7\xe3o n\xe3o estiver\\nmarcada como baseada em ENEM (`baseadoEmEnem: false`), a resposta do caminho\\nde defini\xe7\xe3o tamb\xe9m acumula\\n[`eliminacao_enem_fora_de_processo_enem`](/erros/uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem)\\n\u2014 as duas causas s\xe3o conferidas de forma independente, e nenhuma interrompe\\na passada da outra."],"comoResolver":["Remova todas as regras de elimina\xe7\xe3o da configura\xe7\xe3o quando\\n`regraCalculoCodigo` for `CLASSIFICACAO_IMPORTADA`. Se a inten\xe7\xe3o era\\neliminar por corte de nota, declare `FORMULA_MEDIA_PONDERADA` como regra de\\nc\xe1lculo."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);